# بنية كل درس: الجهاز المفاهيمي (مفهوم مركزي + مفاهيم مجاورة) ← شرح المفاهيم ← التمثيل ← نص تطبيقي (مع أجوبته) ← نص تقويمي.
BOOK = "PH_6CD"

def C(title, pages, central, adjacent, examples, explain, text, intro, app, apps=()):
    """text = (صاحب النص، فكرته، الإشكال المحوري، الأطروحة/العلاقات، الأساليب الحجاجية)"""
    author, gist, problem, thesis, styles = text
    board = [
        {"h": "المفهوم المركزي", "lines": [f"{central[0]}: {central[1]}"]},
        {"h": "المفاهيم المجاورة", "lines": [], "table": [["المفهوم", "تعريفه"]] + [list(a) for a in adjacent]},
        {"h": "شرح وتحليل", "lines": explain},
        {"h": "التمثيل للمفاهيم", "lines": [], "table": [["المفهوم", "مثال"]] + [list(e) for e in examples]},
        {"h": f"النص التطبيقي: {author}", "lines": [gist, "الإشكال المحوري: " + problem, thesis, "الأساليب الحجاجية: " + styles]},
    ]
    return {"title": title, "match": [title], "pages": pages,
            "objectives": [f"أن يعرّف الطالب مفهوم «{central[0]}» ويحدد دلالته.",
                           "أن يميز المفاهيم المجاورة: " + "، ".join(a[0] for a in adjacent) + ".",
                           "أن يحلل نصا فلسفيا: أسئلة الفقرات، الإشكال المحوري، الأطروحة، الأساليب الحجاجية."],
            "intro": intro,
            "summary": f"{central[0]}: {central[1]} " + " ".join(explain) + " ومن المفاهيم المجاورة: " + "؛ ".join(f"{a[0]}: {a[1]}" for a in adjacent) + ".",
            "points": [f"{central[0]}: {central[1]}"] + [f"{a[0]}: {a[1]}" for a in adjacent] + [f"نص {author}: {problem}"],
            "application": {"q": app[0], "a": app[1]},
            "applications": [{"q": q, "a": a} for q, a in apps], "board": board}

